/** Human-controlled preview/send and evidence-backed report history, separate from source diaries. */
final class AnalysisUiController {
    interface Host {void go(String screen,String arg);void settings();void redraw();String device();}
    private final Activity activity;private final ExpansionStore store;private final ActivityHistoryStore activityStore;private final OpenRouterClient client;private final AnalysisController controller;private final Host host;private UiKit ui;
    private LocalDate end=LocalDate.now();private int days=7,historyPage,totalReports;private boolean compare=true,focused,busy,destroyed,historyLoading,historyLoaded;private List<String> domains=new ArrayList<>(AnalysisSnapshot.DOMAINS),exercises=new ArrayList<>();private List<Integer> reps=new ArrayList<>();private String model="",message="",pendingReportId="";private AnalysisSnapshot snapshot,readiness;private boolean readinessLoading,readinessChecked;private int readinessGeneration;private final java.util.Map<String,Boolean> sections=new java.util.HashMap<>();private JSONObject selectedHistory;private String historySelection="";private List<JSONObject> history=Collections.emptyList();private EditText credentialField;private boolean hasKey;
    AnalysisUiController(Activity activity,ExpansionStore store,ActivityHistoryStore activityStore,OpenRouterClient client,Host host){this.activity=activity;this.store=store;this.activityStore=activityStore;this.client=client;this.host=host;controller=new AnalysisController(store,activityStore,client);}
    void pause(){controller.cancel();busy=false;snapshot=null;readiness=null;readinessLoading=false;readinessChecked=false;readinessGeneration++;if(credentialField!=null){credentialField.setText("");credentialField=null;}}
    void destroy(){destroyed=true;pause();controller.destroy();}
    void invalidate(){controller.cancel();snapshot=null;readiness=null;readinessLoading=false;readinessChecked=false;readinessGeneration++;busy=false;history=Collections.emptyList();historyLoaded=false;}
    void save(Bundle state){Bundle openSections=new Bundle();for(java.util.Map.Entry<String,Boolean> section:sections.entrySet())openSections.putBoolean(section.getKey(),section.getValue());state.putBundle("analysis.sections",openSections);state.putString("analysis.end",end.toString());state.putInt("analysis.days",days);state.putBoolean("analysis.compare",compare);state.putBoolean("analysis.focused",focused);state.putString("analysis.domains",new JSONArray(domains).toString());state.putString("analysis.exercises",new JSONArray(exercises).toString());state.putString("analysis.reps",new JSONArray(reps).toString());state.putString("analysis.export.id",pendingReportId);}
    void restore(Bundle state){if(state==null)return;Bundle openSections=state.getBundle("analysis.sections");if(openSections!=null)for(String key:openSections.keySet())sections.put(key,openSections.getBoolean(key));try{List<String> d=new ArrayList<>(),e=new ArrayList<>();List<Integer> r=new ArrayList<>();JSONArray ds=new JSONArray(state.getString("analysis.domains","[]")),es=new JSONArray(state.getString("analysis.exercises","[]")),rs=new JSONArray(state.getString("analysis.reps","[]"));for(int i=0;i<ds.length();i++)d.add(ds.optString(i));for(int i=0;i<es.length();i++)e.add(es.optString(i));for(int i=0;i<rs.length();i++)r.add(rs.optInt(i));AnalysisSnapshot.Selection selected=new AnalysisSnapshot.Selection(LocalDate.parse(state.getString("analysis.end",end.toString())),ZoneId.systemDefault(),state.getInt("analysis.days",7),state.getBoolean("analysis.compare",true),state.getBoolean("analysis.focused"),"",d,e,r);end=selected.end;days=selected.days;compare=selected.compare;focused=selected.focused;domains=new ArrayList<>(d);exercises=new ArrayList<>(e);reps=new ArrayList<>(r);String export=state.getString("analysis.export.id","");if(!export.isEmpty())NutritionModels.id(export);pendingReportId=export;}catch(Exception e){snapshot=null;}}
    void build(LinearLayout page,UiKit kit,String screen,String arg){ui=kit;if(!message.isEmpty())note(page,message);if("openrouter".equals(screen))settings(page);else if("analysis_history".equals(screen))history(page,arg);else analysis(page);}
    private AnalysisSnapshot.Selection selection(){return new AnalysisSnapshot.Selection(end,ZoneId.systemDefault(),days,compare,focused,host.device(),domains,exercises,reps);}
    private void changed(){controller.cancel();snapshot=null;readiness=null;readinessLoading=false;readinessChecked=false;readinessGeneration++;busy=false;message="";host.redraw();}
    private void analysis(LinearLayout page){
        title(page,"Разбор с ИИ");
        button(page,"Последний день: "+end,()->{DatePickerDialog picker=new DatePickerDialog(ui.dialogContext(),(d,y,m,day)->{end=LocalDate.of(y,m+1,day);changed();},end.getYear(),end.getMonthValue()-1,end.getDayOfMonth());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();ui.dialog(picker);});
        page.addView(ui.segmented(new String[]{"День","7 дней","30 дней"},days==1?0:days==7?1:2,index->{days=new int[]{1,7,30}[index];if(days==1)compare=false;changed();}),ui.fillWrap(4,8));
        note(page,(days==30?"30 дней подряд, а не календарный месяц. ":"")+"Период: "+end.minusDays(days-1L)+" — "+end);
        button(page,"Области: "+domainNames(domains),this::chooseDomains);
        if(readiness==null&&!readinessLoading&&!readinessChecked)loadReadiness();
        if(readinessLoading)note(page,"Проверяю сохранённые данные…");else if(readiness!=null&&snapshot==null){LinearLayout local=new LinearLayout(activity);local.setOrientation(LinearLayout.VERTICAL);local.setPadding(ui.dp(12),ui.dp(8),ui.dp(12),ui.dp(8));ui.card(local);page.addView(local,ui.fillWrap(4,8));local.addView(ui.iconHeading("Данные за период",UiIcons.Kind.CHART),ui.fillWrap(4,8));note(local,"Снимок: "+java.time.Instant.ofEpochMilli(readiness.preparedAt).atZone(ZoneId.systemDefault()).toLocalTime().withSecond(0).withNano(0));renderMetrics(local,readiness.payload());button(local,"Обновить локальные данные",this::changed);}
        if(days==1)note(page,"Сон относится к дню пробуждения. Пульс и SpO₂ — отдельные наблюдения. Сегодня ещё не завершён.");
        model=client.selected(false);note(page,client.selectionLabel(false));button(page,"Модели OpenRouter в настройках",host::settings);
        LinearLayout advanced=ui.disclosure(page,"Настройки анализа","analysis.advanced",sections);
        CheckBox comparison=check(advanced,"Сравнить с предыдущим таким же периодом",compare);comparison.setOnCheckedChangeListener((v,on)->{compare=on;changed();});
        CheckBox detail=check(advanced,"Подробные суточные серии",focused);detail.setOnCheckedChangeListener((v,on)->{focused=on;changed();});
        if(domains.contains("strength")){button(advanced,"Упражнения: "+exercises.size()+" из максимум 8",this::chooseExercises);button(advanced,"Повторы: "+reps+" (до 10 значений)",this::chooseReps);note(advanced,"Без выбора передаются только итоги зарегистрированных подходов.");}

        Button prepare=ui.iconAction(busy?"Подготовка…":"Подготовить данные для просмотра",UiIcons.Kind.SPARKLES,snapshot==null,()->{busy=true;message="";snapshot=null;host.redraw();controller.prepare(selection(),(prepared,error)->{busy=false;if(prepared==null)message=error.contains("LIMIT")?"История превышает безопасный предел. Выберите короче период или меньше областей.":"Не удалось подготовить сохранённые данные.";else snapshot=prepared;host.redraw();});});prepare.setEnabled(!busy);page.addView(prepare,ui.fillWrap(8,8));
        if(snapshot!=null){
            title(page,"Перед отправкой");note(page,"Подготовлено: "+java.time.Instant.ofEpochMilli(snapshot.preparedAt).atZone(ZoneId.systemDefault()).toLocalTime().withSecond(0).withNano(0));note(page,"Период: "+snapshot.selection().end.minusDays(snapshot.selection().days-1L)+" — "+snapshot.selection().end+(snapshot.selection().compare?" · с предыдущим таким же периодом":""));
            note(page,"Будут отправлены локальные сводки, покрытия и разрешённые сравнения. Имя, абсолютные даты, UUID, адрес часов, GPS, заметки, фотографии и сырые ряды исключены.");
            LinearLayout exact=ui.disclosure(page,"Показатели и точные данные","analysis.exact",sections);renderMetrics(exact,snapshot.payload());button(exact,"Точный JSON отправляемых данных",()->showJson("Передаваемые данные",snapshot.payload()));button(exact,"Все локальные основания",()->showEvidenceKeys(snapshot.evidence()));
            Button send=make(busy?"Запрос выполняется…":"Отправить эти данные один раз",()->{AnalysisSnapshot frozen=snapshot;model=client.selected(false);if(model.isEmpty()){message="Выберите модель в настройках OpenRouter.";sections.put("analysis.advanced",true);host.redraw();return;}busy=true;message="";host.redraw();controller.send(frozen,model,(report,error)->{busy=false;if(report==null){message=OpenRouterClient.message(error);if("SOURCE_CHANGED".equals(error)){snapshot=null;readiness=null;readinessChecked=false;}host.redraw();}else{history=Collections.emptyList();historyLoaded=false;host.go("analysis_history",report.optString("id"));loadHistory();}});});send.setEnabled(!busy&&!client.busy());page.addView(send,ui.fillWrap(8,8));
            if(busy)button(page,"Отменить запрос",()->{controller.cancel();busy=false;message="Запрос отменён. Новая отправка возможна только вручную.";host.redraw();});
        }
        page.addView(ui.settingRow("История разборов","Сохранённые отчёты и основания",UiIcons.Kind.HISTORY,false,()->{host.go("analysis_history","");loadHistory();}),ui.fillWrap(8,8));
    }
    private void loadReadiness(){
        readinessLoading=true;int expected=++readinessGeneration;AnalysisSnapshot.Selection chosen=selection();
        store.submit(()->AnalysisSnapshot.prepare(chosen,AnalysisSnapshot.capture(store,activityStore,chosen)),(local,error)->{if(destroyed||expected!=readinessGeneration)return;readinessLoading=false;readinessChecked=true;readiness=local;if(local==null)message=error.contains("LIMIT")?"Для обзора выберите короче период или меньше областей.":"Не удалось проверить локальные данные.";host.redraw();});
    }
    private void renderMetrics(LinearLayout page,JSONObject payload){
        JSONArray values=payload.optJSONArray("domains");if(values==null)return;
        for(int i=0;i<values.length();i++){JSONObject domain=values.optJSONObject(i);String name=domain.optString("domain");page.addView(ui.iconHeading(domainName(name),domainIcon(name)),ui.fillWrap(12,4));note(page,availability(domain.optString("availability"))+" · "+quality(domain.optString("qualityCeiling")));
            JSONArray metrics=domain.optJSONArray("metrics");if(metrics==null)continue;int shown=0;for(int j=0;j<metrics.length();j++){JSONObject metric=metrics.optJSONObject(j);String id=metric.optString("id");if(!overviewMetric(id))continue;note(page,metricLabel(id)+": "+metricValue(metric));if(++shown>=4)break;}
        }
        note(page,"Пропуски не заменяются нулями. Пульс и SpO₂ не являются непрерывным мониторингом; калории часов имеют исходные единицы.");
    }
    private static boolean overviewMetric(String id){return id.endsWith("period.observedDays")||id.endsWith("period.sampleCount")||id.endsWith("period.registeredKcalMilli")||id.endsWith("period.pooledMedianBpm")||id.endsWith("period.pooledMedianPercent")||id.endsWith("period.pooledMedianPercentagePoints")||id.endsWith("period.meanSelectedAsleepSeconds")||id.endsWith("period.watchMeanLastObservedStepsSnapshot")||id.endsWith("period.meanDailyMedianKg")||id.endsWith("period.doneWorkSetCount");}
    private void chooseDomains(){String[] names=new String[AnalysisSnapshot.DOMAINS.size()];boolean[] chosen=new boolean[names.length];for(int i=0;i<names.length;i++){names[i]=domainName(AnalysisSnapshot.DOMAINS.get(i));chosen[i]=domains.contains(AnalysisSnapshot.DOMAINS.get(i));}ui.dialogBuilder().setTitle("Области анализа").setMultiChoiceItems(names,chosen,(dialog,index,on)->chosen[index]=on).setPositiveButton("Применить",(dialog,which)->{List<String> next=new ArrayList<>();for(int i=0;i<chosen.length;i++)if(chosen[i])next.add(AnalysisSnapshot.DOMAINS.get(i));if(next.isEmpty()){message="Выберите хотя бы одну область.";host.redraw();return;}domains=next;changed();}).setNeutralButton("Все",(dialog,which)->{domains=new ArrayList<>(AnalysisSnapshot.DOMAINS);focused=false;changed();}).setNegativeButton("Отмена",null).show();}
    private void chooseExercises(){busy=true;host.redraw();AnalysisSnapshot.Selection selected=selection();store.submit(()->AnalysisStrengthSummary.choices(AnalysisSnapshot.capture(store,activityStore,selected)),(choices,error)->{busy=false;if(destroyed)return;if(choices==null){message="Не удалось открыть силовую историю.";host.redraw();return;}String[] labels=new String[choices.size()];boolean[] chosen=new boolean[choices.size()];for(int i=0;i<labels.length;i++){labels[i]=choices.get(i).optString("label");chosen[i]=exercises.contains(choices.get(i).optString("key"));}ui.dialogBuilder().setTitle("До 8 конкретных упражнений и оборудования").setMultiChoiceItems(labels,chosen,(dialog,index,on)->chosen[index]=on).setPositiveButton("Применить",(dialog,which)->{List<String> next=new ArrayList<>();for(int i=0;i<chosen.length;i++)if(chosen[i])next.add(choices.get(i).optString("key"));if(next.size()>8){message="Выберите не более 8 упражнений. Выбор не был усечён.";host.redraw();return;}exercises=next;changed();}).setNegativeButton("Отмена",null).show();host.redraw();});}
    private void chooseReps(){EditText field=new EditText(activity);field.setInputType(InputType.TYPE_CLASS_TEXT);field.setText(android.text.TextUtils.join(", ",reps));field.setHint("Например 5, 8, 10, 12");AlertDialog dialog=ui.dialogBuilder().setTitle("До 10 значений повторов").setView(field).setPositiveButton("Применить",null).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(v->{ui.dialog(dialog);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{try{List<Integer> values=new ArrayList<>();String text=field.getText().toString().trim();if(!text.isEmpty())for(String part:text.split(",")){int n=Integer.parseInt(part.trim());if(n<1||n>1000||values.contains(n))throw new IllegalArgumentException();values.add(n);}if(values.size()>10)throw new IllegalArgumentException();reps=values;dialog.dismiss();changed();}catch(RuntimeException e){field.setError("До 10 разных целых чисел от 1 до 1000");}});});dialog.show();}
    private void chooseModel(boolean photo){LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(ui.dp(12),ui.dp(6),ui.dp(12),ui.dp(6));EditText search=new EditText(ui.dialogContext());search.setHint("Поиск по названию или точному ID");form.addView(search);android.widget.ListView list=new android.widget.ListView(activity);form.addView(list,new LinearLayout.LayoutParams(-1,0,1));List<OpenRouterModelCatalog.Model> filtered=new ArrayList<>();android.widget.BaseAdapter adapter=new android.widget.BaseAdapter(){public int getCount(){return filtered.size();}public Object getItem(int i){return filtered.get(i);}public long getItemId(int i){return i;}public boolean areAllItemsEnabled(){return false;}public boolean isEnabled(int i){return filtered.get(i).incompatibility(photo).isEmpty();}public android.view.View getView(int i,android.view.View recycled,android.view.ViewGroup parent){OpenRouterModelCatalog.Model m=filtered.get(i);android.widget.TextView row=recycled instanceof android.widget.TextView?(android.widget.TextView)recycled:ui.label("",14,ui.text);row.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));row.setMinHeight(ui.dp(48));String reason=m.incompatibility(photo);row.setText(m.name+"\n"+m.id+"\n"+(reason.isEmpty()?m.priceLabel():reason));row.setTextColor(reason.isEmpty()?ui.text:ui.muted);row.setEnabled(reason.isEmpty());return row;}};list.setAdapter(adapter);AlertDialog dialog=ui.dialogBuilder().setTitle(photo?"Модель для фото еды":"Модель для анализа").setView(form).setNegativeButton("Закрыть",null).create();Runnable render=()->{filtered.clear();String query=search.getText().toString().trim().toLowerCase(java.util.Locale.ROOT);for(OpenRouterModelCatalog.Model m:client.catalog.all())if((m.id+" "+m.name).toLowerCase(java.util.Locale.ROOT).contains(query))filtered.add(m);adapter.notifyDataSetChanged();};list.setOnItemClickListener((parent,view,index,id)->{OpenRouterModelCatalog.Model m=filtered.get(index);if(!m.incompatibility(photo).isEmpty())return;Runnable apply=()->{try{client.select(m.id,photo);controller.cancel();snapshot=null;busy=false;dialog.dismiss();host.redraw();}catch(RuntimeException e){message=OpenRouterClient.message("MODEL_RELOAD_SELECT_REQUIRED");dialog.dismiss();host.redraw();}};if(m.free)apply.run();else ui.dialogBuilder().setTitle("Выбрать модель с этими тарифами?").setMessage(m.priceLabel()+"\nОсновные тарифы ограничены. Кэш может оплачиваться отдельно; итоговая стоимость зависит от запроса. Отправка выполняется отдельным нажатием.").setPositiveButton("Выбрать",(d,w)->apply.run()).setNegativeButton("Отмена",null).show();});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence t,int start,int count,int after){}public void onTextChanged(CharSequence t,int start,int before,int count){render.run();}public void afterTextChanged(android.text.Editable t){}});render.run();dialog.show();ui.dialog(dialog);if(dialog.getWindow()!=null){dialog.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);dialog.getWindow().setLayout(-1,Math.round(activity.getResources().getDisplayMetrics().heightPixels*.8f));}}
    private void settings(LinearLayout page){title(page,"Личный OpenRouter");note(page,"Личный ключ защищён на этом устройстве и не входит в экспорт. Отправка фото и показателей выполняется только по вашему нажатию.");note(page,hasKey?"Личный ключ сохранён на этом устройстве.":"Личный ключ не задан или защищённое хранилище недоступно.");button(page,"Ввести или заменить ключ",this::credentialDialog);button(page,"Удалить личный ключ",()->ui.dialogBuilder().setTitle("Удалить ключ с этого устройства?").setMessage("Активные запросы будут отменены.").setPositiveButton("Удалить",(d,w)->store.submit(()->{client.credentials.remove();return true;},(ok,error)->{hasKey=false;invalidate();message=error.isEmpty()?"Ключ удалён.":"Не удалось удалить ключ.";host.redraw();})).setNegativeButton("Отмена",null).show());button(page,"Проверить ключ",()->{message="Проверяю ключ…";host.redraw();client.checkKey((value,error)->{if(destroyed)return;message=error.isEmpty()?"Ключ принят сервисом. Это не подтверждает доступность выбранного приватного провайдера.":OpenRouterClient.message(error);host.redraw();});});button(page,"Обновить каталог моделей для этого ключа",()->{message="Загружаю метаданные каталога…";host.redraw();client.reloadModels((value,error)->{if(destroyed)return;message=error.isEmpty()?"Всего моделей: "+client.catalog.all().size()+". Совместимых для анализа: "+client.catalog.models(false).size()+", для фото: "+client.catalog.models(true).size()+". Приватность и фактическая доступность проверятся при ручной отправке.":OpenRouterClient.message(error);host.redraw();});});LinearLayout technical=ui.disclosure(page,"Приватность и стоимость","settings.technical",sections);note(technical,"Ключ зашифрован на устройстве и не включается в резервные копии, журналы и экспорт.");note(technical,"Запрос отправляется выбранной модели без автоматической замены. Сервису запрещены сохранение и сбор данных. Кэш может оплачиваться отдельно; итоговая стоимость зависит от запроса.");note(page,"Для анализа: "+client.selectionLabel(false));button(page,"Выбрать модель анализа",()->chooseModel(false));note(page,"Для фото еды: "+client.selectionLabel(true));button(page,"Выбрать модель фото",()->chooseModel(true));button(page,"Отменить текущий сетевой запрос",()->{client.cancel();message="Запрос отменён.";host.redraw();});store.submit(()->client.credentials.hasKey(),(present,error)->{if(destroyed)return;boolean next=Boolean.TRUE.equals(present);if(next!=hasKey){hasKey=next;host.redraw();}});}
    private void credentialDialog(){EditText key=new EditText(activity);credentialField=key;key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setSaveEnabled(false);key.setSaveFromParentEnabled(false);key.setTag("openrouter.secret");key.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);key.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);AlertDialog dialog=ui.dialogBuilder().setTitle("Ваш личный ключ").setView(key).setPositiveButton("Зашифровать и сохранить",null).setNegativeButton("Отмена",null).create();dialog.setOnDismissListener(d->{key.setText("");if(credentialField==key)credentialField=null;});dialog.setOnShowListener(d->{ui.dialog(dialog);if(dialog.getWindow()!=null)dialog.getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String entered=key.getText().toString();key.setText("");store.submit(()->{client.credentials.save(entered);return true;},(ok,error)->{if(destroyed)return;if(error.isEmpty()){hasKey=true;invalidate();message="Ключ сохранён защищённо.";dialog.dismiss();host.redraw();}else key.setError("Не удалось сохранить ключ. Проверьте формат и доступность Keystore.");});});});dialog.show();}
    void openHistory(String id){historySelection=id;historyLoaded=false;selectedHistory=null;loadHistory();}
    private void loadHistory(){if(historyLoading||destroyed)return;historyLoading=true;String selected=historySelection;controller.history(historyPage,selected,(values,error)->{historyLoading=false;if(destroyed)return;if(!selected.equals(historySelection)){loadHistory();return;}historyLoaded=true;if(values==null)message="Не удалось открыть историю отчётов.";else{history=values.reports;selectedHistory=values.selected;totalReports=values.total;historyPage=values.page;}host.redraw();});}
    private void history(LinearLayout page,String id){
        if(!id.equals(historySelection))openHistory(id);if(!historyLoaded&&!historyLoading)loadHistory();
        JSONObject selected=id.equals(historySelection)?selectedHistory:null;
        if(selected==null){
            title(page,"История разборов");if(historyLoading)note(page,"Проверка сохранённых оснований…");
            note(page,"Отчётов: "+totalReports+" · страница "+(historyPage+1));
            if(historyPage>0)button(page,"Более новые отчёты",()->{historyPage--;historyLoaded=false;loadHistory();host.redraw();});
            for(JSONObject report:history){String date=java.time.Instant.ofEpochMilli(report.optLong("createdAt")).atZone(ZoneId.systemDefault()).toLocalDateTime().withSecond(0).withNano(0).toString();String reportId=report.optString("id");page.addView(ui.settingRow(date,report.optString("modelId")+(report.optBoolean("stale")?" · данные изменились":""),UiIcons.Kind.HISTORY,false,()->host.go("analysis_history",reportId)),ui.fillWrap(4,8));}
            if((historyPage+1)*150<totalReports)button(page,"Более ранние отчёты",()->{historyPage++;historyLoaded=false;loadHistory();host.redraw();});
            if(history.isEmpty()&&!historyLoading)note(page,"Сохранённых разборов пока нет.");return;
        }
        JSONObject report=selected,saved=report.optJSONObject("snapshot"),response=report.optJSONObject("response"),selection=saved.optJSONObject("selection"),evidence=saved.optJSONObject("evidence");
        title(page,"Разбор показателей");note(page,"Последний день: "+selection.optString("end")+" · "+selection.optInt("days")+" дней");
        if(report.optBoolean("stale")){LinearLayout stale=reportCard(page,true);note(stale,"Источники изменились после этого снимка. Отчёт описывает сохранённые данные; для текущих показателей подготовьте новый разбор.");}
        JSONArray combined=response.optJSONArray("combined");
        if(combined!=null&&combined.length()>0){LinearLayout brief=reportCard(page,true);brief.addView(ui.iconHeading("Краткое резюме",UiIcons.Kind.SPARKLES),ui.fillWrap(4,8));
            for(int i=0;i<Math.min(2,combined.length());i++){JSONObject claim=combined.optJSONObject(i);brief.addView(ui.label(claim.optString("statement"),18,ui.text),ui.fillWrap(4,8));inlineEvidence(brief,claim.optJSONArray("evidenceRefs"),evidence,"combined."+i);}
            if(combined.length()>2){LinearLayout more=ui.disclosure(brief,"Другие совместные наблюдения","report.combined.more",sections);for(int i=2;i<combined.length();i++){JSONObject claim=combined.optJSONObject(i);claimCard(more,claim.optString("statement"),claim.optJSONArray("evidenceRefs"),evidence);}}
        }
        JSONArray ds=response.optJSONArray("domains");
        if(ds!=null)for(int i=0;i<ds.length();i++){
            JSONObject domain=ds.optJSONObject(i);String name=domain.optString("domain");LinearLayout card=reportCard(page,false);
            card.addView(ui.iconHeading(domainName(name),domainIcon(name)),ui.fillWrap(4,8));note(card,quality(domain.optString("status")));card.addView(ui.label(domain.optString("summary"),16,ui.text),ui.fillWrap(4,8));
            JSONArray observations=domain.optJSONArray("observations"),suggestions=domain.optJSONArray("suggestions"),limitations=domain.optJSONArray("limitations");
            if(observations!=null&&observations.length()>0){LinearLayout details=ui.disclosure(card,"Наблюдения и основания","report."+name+".observations",sections);for(int j=0;j<observations.length();j++){JSONObject claim=observations.optJSONObject(j);claimCard(details,claim.optString("statement"),claim.optJSONArray("evidenceRefs"),evidence);}}
            if(suggestions!=null&&suggestions.length()>0){LinearLayout steps=ui.disclosure(card,"Предложения по этим данным","report."+name+".suggestions",sections);for(int j=0;j<suggestions.length();j++){JSONObject claim=suggestions.optJSONObject(j);claimCard(steps,claim.optString("action")+"\n"+claim.optString("rationale"),claim.optJSONArray("evidenceRefs"),evidence);}}
            if(limitations!=null)for(int j=0;j<limitations.length();j++)note(card,"Ограничение: "+limitations.optString(j));
        }
        LinearLayout sources=ui.settingDisclosure(page,"Основания и покрытие данных","Что учтено и какие ограничения сохранены",UiIcons.Kind.CHART,"report.sources",sections);renderMetrics(sources,saved.optJSONObject("payload"));button(sources,"Все локальные основания",()->showEvidenceKeys(evidence));
        note(page,"ИИ может ошибаться. Сверяйте выводы с показателями и основаниями отчёта.");
        LinearLayout actions=ui.disclosure(page,"Модель, снимок и экспорт","report.actions",sections);note(actions,"Модель: "+report.optString("modelId"));
        button(actions,"Экспортировать этот отчёт JSON",()->{pendingReportId=report.optString("id");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"analysis-report.json");activity.startActivityForResult(intent,ExpansionUiController.ANALYSIS_EXPORT);});
        button(actions,"Показать сохранённый снимок",()->showJson("Сохранённые метрики",saved.optJSONObject("payload")));button(actions,"Обновить отметки устаревания",()->{history=Collections.emptyList();historyLoaded=false;loadHistory();});
    }
    private LinearLayout reportCard(LinearLayout page,boolean tinted){LinearLayout card=new LinearLayout(activity);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(ui.dp(16),ui.dp(12),ui.dp(16),ui.dp(12));if(tinted)ui.tintedCard(card);else ui.card(card);page.addView(card,ui.fillWrap(4,12));return card;}
    private static UiIcons.Kind domainIcon(String domain){switch(domain){case "nutrition":return UiIcons.Kind.FOOD;case "activity":return UiIcons.Kind.ACTIVITY;case "sleep":return UiIcons.Kind.MOON;case "heart":return UiIcons.Kind.HEART;case "spo2":return UiIcons.Kind.DROPLET;case "strength":return UiIcons.Kind.DUMBBELL;case "weight":return UiIcons.Kind.SCALE;default:return UiIcons.Kind.CHART;}}
    void documentResult(int request,int result,Intent intent){if(request!=ExpansionUiController.ANALYSIS_EXPORT||result!=Activity.RESULT_OK||intent==null||intent.getData()==null||pendingReportId.isEmpty())return;String id=pendingReportId;pendingReportId="";android.net.Uri uri=intent.getData();store.submit(()->{JSONObject report=store.analysisReport(id);if(report==null)throw new IllegalStateException("REPORT_MISSING");JSONObject local=report.optJSONObject("snapshot"),selection=local.optJSONObject("selection");JSONObject exported=NutritionModels.object("schemaVersion",1,"createdAt",report.opt("createdAt"),"modelId",report.opt("modelId"),"rulesVersion",report.opt("rulesVersion"),"localEndDay",selection.optString("end"),"days",selection.opt("days"),"sourceRevisionHash",local.optString("sourceRevisionHash"),"payload",local.optJSONObject("payload"),"evidence",local.optJSONObject("evidence"),"response",report.optJSONObject("response"));byte[] bytes=exported.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>256*1024)throw new IllegalArgumentException("REPORT_SIZE");try(java.io.OutputStream output=activity.getContentResolver().openOutputStream(uri,"wt")){if(output==null)throw new java.io.IOException();output.write(bytes);}return true;},(ok,error)->{if(destroyed)return;message=error.isEmpty()?"Отчёт экспортирован без ключа и исходных идентификаторов.":"Не удалось экспортировать отчёт.";host.redraw();});}
    private void claimCard(LinearLayout page,String statement,JSONArray refs,JSONObject evidence){LinearLayout card=reportCard(page,false);card.addView(ui.label(statement,16,ui.text),ui.fillWrap(4,8));inlineEvidence(card,refs,evidence,"claim."+statement.hashCode());}
    private void inlineEvidence(LinearLayout page,JSONArray refs,JSONObject evidence,String key){
        LinearLayout content=ui.disclosure(page,"Основания этого вывода","report.evidence."+key,sections);JSONObject shown=new JSONObject();
        if(refs!=null)for(int i=0;i<refs.length();i++){String ref=refs.optString(i);JSONObject metric=evidence.optJSONObject(ref);if(metric==null)continue;NutritionModels.put(shown,ref,metric);content.addView(ui.label(evidenceLabel(ref),14,ui.text),ui.fillWrap(8,4));note(content,metricValue(metric));if(metric.has("sampleCount")&&!metric.isNull("sampleCount"))note(content,"Количество записей: "+metric.optInt("sampleCount"));JSONArray flags=metric.optJSONArray("qualityFlags");if(flags!=null)for(int f=0;f<flags.length();f++)note(content,limitationName(flags.optString(f)));if(!metric.optString("basis").isEmpty())note(content,basisName(metric.optString("basis")));}
        button(content,"Точный JSON оснований",()->showJson("Основания выбранного утверждения",shown));
    }
    private void showEvidenceKeys(JSONObject evidence){JSONArray keys=new JSONArray();java.util.Iterator<String> names=evidence.keys();while(names.hasNext())keys.put(names.next());showEvidence(keys,evidence);}
    private void showEvidence(JSONArray refs,JSONObject evidence){
        LinearLayout content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(ui.dp(12),ui.dp(8),ui.dp(12),ui.dp(8));JSONObject shown=new JSONObject();
        if(refs!=null)for(int i=0;i<refs.length();i++){String ref=refs.optString(i);JSONObject metric=evidence.optJSONObject(ref);if(metric==null)continue;NutritionModels.put(shown,ref,metric);title(content,evidenceLabel(ref));note(content,metricValue(metric));if(metric.has("sampleCount")&&!metric.isNull("sampleCount"))note(content,"Количество записей: "+metric.optInt("sampleCount"));if(metric.has("nPairedDays"))note(content,"Совпадающих дней: "+metric.optInt("nPairedDays"));
            JSONArray flags=metric.optJSONArray("qualityFlags");if(flags!=null)for(int f=0;f<flags.length();f++)note(content,limitationName(flags.optString(f)));if(!metric.optString("basis").isEmpty())note(content,basisName(metric.optString("basis")));
        }
        button(content,"Точный JSON оснований",()->showJson("Основания выбранного утверждения",shown));android.widget.ScrollView scroll=new android.widget.ScrollView(activity);scroll.addView(content);ui.dialogBuilder().setTitle("Основания вывода").setView(scroll).setPositiveButton("Закрыть",null).show();
    }
    private static String metricLabel(String id){String key=id.substring(id.lastIndexOf('.')+1).replaceAll("\\[[^]]*\\]","");switch(key){case "observedDays":return "Дней с данными";case "eligibleDays":return "Дней, пригодных для расчёта";case "missingDays":return "Дней без данных";case "sampleCount":return "Наблюдений";case "excludedRecordCount":return "Исключено записей";case "registeredKcalMilli":return "Подтверждённая еда";case "registeredProteinMg":return "Белки";case "registeredFatMg":return "Жиры";case "registeredCarbohydrateMg":return "Углеводы";case "pooledMedianBpm":return "Медиана пульса";case "pooledMeanBpm":return "Средний пульс";case "pooledMedianPercent":case "pooledMedianPercentagePoints":return "Медиана SpO₂";case "meanSelectedAsleepSeconds":return "Средняя длительность сна";case "watchMeanLastObservedStepsSnapshot":return "Среднее последних записей шагов за день";case "watchStepsObserved":case "watchStepsLastPerDaySum":return "Шаги часов за дни с записями";case "meanDailyMedianKg":return "Средний вес по медианам дней";case "latestKg":return "Последний вес";case "doneWorkSetCount":case "setCount":return "Рабочих подходов";case "loadDeltaGrams":return "Изменение зарегистрированного веса";case "improvementGrams":return "Изменение с учётом помощи тренажёра";case "loadDeltaPercent":return "Изменение веса в процентах";case "maxRepsInWorkSet":return "Максимум повторов в рабочем подходе";case "loadMode":return "Способ учёта веса";case "comparable":return "Данные сопоставимы";case "meanKcalMilliCompleteDays":return "Средние калории в полностью заполненные дни";case "selectedAsleepSeconds":return "Длительность сна";case "selectedAwakeSeconds":return "Бодрствование в интервале сна";case "selectedLightSeconds":return "Лёгкий сон";case "selectedDeepSeconds":return "Глубокий сон";case "selectedIntervalSeconds":return "Сохранённый интервал сна";case "bestLoadGramsByReps":return "Лучший вес по числу повторов";case "totalReps":return "Всего повторов";case "meanDailyMedianBpm":return "Среднее дневных медиан пульса";case "meanDailyMedianPercent":return "Среднее дневных медиан SpO₂";case "meanBpm":return "Средний пульс";case "minBpm":return "Минимальный пульс";case "maxBpm":return "Максимальный пульс";case "medianBpm":return "Медиана пульса";case "medianPercent":return "Медиана SpO₂";case "meanPercent":return "Средний SpO₂";case "minPercent":return "Минимальный SpO₂";case "maxPercent":return "Максимальный SpO₂";case "confirmedEntryCount":return "Подтверждённых приёмов пищи";case "confirmedItemCount":return "Продуктов";case "macrosKnownItems":return "Продуктов с полными БЖУ";case "photoEstimatedItems":return "Продуктов с оценкой по фото";default:return "Показатель из сохранённого снимка";}}
    private static String evidenceLabel(String id){
        if(id.startsWith("paired."))return "Совместные наблюдения";
        String domain=id.contains(".")?domainName(id.substring(0,id.indexOf('.'))):"Показатель";String context="";
        java.util.regex.Matcher day=java.util.regex.Pattern.compile("day\\[(-?[0-9]+)\\]").matcher(id);
        if(day.find()){int relative=Integer.parseInt(day.group(1));context=relative==0?" · последний день":" · за "+Math.abs(relative)+" дней до последнего дня";}
        java.util.regex.Matcher exercise=java.util.regex.Pattern.compile("exercise\\[e([0-9]+)\\]").matcher(id);if(exercise.find())context+=" · выбранное упражнение "+Integer.parseInt(exercise.group(1));
        java.util.regex.Matcher repetitions=java.util.regex.Pattern.compile("(?:reps|bestLoadGramsByReps)\\[([0-9]+)\\]").matcher(id);if(repetitions.find())context+=" · "+repetitions.group(1)+" повторов";
        if(id.contains("comparison."))context+=" · сравнение периодов";
        return domain+context+" · "+metricLabel(id);
    }
    private static String metricValue(JSONObject metric){
        if(metric.has("nPairedDays")){
            JSONArray domains=metric.optJSONArray("domains");if(domains==null||domains.length()!=2)return metric.optInt("nPairedDays")+" совпадающих дней";
            return "Совпадающих дней: "+metric.optInt("nPairedDays")+"\n"+pairedValue(domains.optString(0),metric.opt("firstMean"))+"\n"+pairedValue(domains.optString(1),metric.opt("secondMean"))+"\nСовпадение по дням не доказывает причинную связь.";
        }
        if(metric.isNull("value"))return "нет данных";Object value=metric.opt("value");String unit=metric.optString("unit");
        if(value instanceof Number){double number=((Number)value).doubleValue();if("kcalMilli".equals(unit))return decimalNumber(number/1000.0)+" ккал";if("mg".equals(unit))return decimalNumber(number/1000.0)+" г";return decimalNumber(number)+" "+unitName(unit);}
        if("mode".equals(unit)){switch(String.valueOf(value)){case "BODYWEIGHT":return "Собственный вес";case "ASSISTANCE":return "Помощь тренажёра";case "EXTERNAL":return "Внешний вес";default:return "Способ учёта указан в точных данных.";}}
        if("variantId".equals(unit)||"group".equals(unit))return "Описание выбранного упражнения доступно в точных данных.";
        if(value instanceof Boolean)return Boolean.TRUE.equals(value)?"да":"нет";
        if(value instanceof JSONObject||value instanceof JSONArray)return "Подробные значения доступны в точном JSON ниже.";
        return value==null?"нет значения":String.valueOf(value);
    }
    private static String decimalNumber(double number){return java.math.BigDecimal.valueOf(number).stripTrailingZeros().toPlainString();}
    private static String pairedValue(String domain,Object value){
        if(!(value instanceof Number))return domainName(domain)+": нет значения";double number=((Number)value).doubleValue();
        switch(domain){case "sleep":return "Сон: средняя длительность "+decimalNumber(number)+" сек";case "heart":return "Пульс: среднее дневных медиан "+decimalNumber(number)+" уд/мин";case "activity":return "Активность: в среднем "+decimalNumber(number)+" сохранённых тренировок телефона за день";case "nutrition":return "Питание: в среднем "+decimalNumber(number/1000.0)+" ккал";case "strength":return "Силовые: средний лучший вес "+decimalNumber(number/1000.0)+" кг для выбранного упражнения и повторов";default:return "Среднее зарегистрированное значение: "+decimalNumber(number);}
    }
    private static String unitName(String unit){switch(unit){case "steps":return "шагов";case "bpm":return "уд/мин";case "percent":case "%":return "%";case "days":return "дней";case "seconds":return "сек";case "kg":return "кг";case "count":return "записей";case "raw":case "unknown":case "watchCalorieRaw":return "исходных единиц";case "ms":return "мс";case "m":return "м";case "grams":return "г";case "reps":return "повторов";case "percentagePoints":return "процентных пунктов";default:return "(единица указана в точных данных)";}}
    private static String limitationName(String flag){switch(flag){case "PARTIAL_HISTORY":return "Ограничение: история может быть неполной.";case "SPARSE_OBSERVATIONS":return "Ограничение: отдельные наблюдения, не непрерывный мониторинг.";case "UNKNOWN_UNIT":return "Ограничение: единица часов не подтверждена.";case "PHOTO_ESTIMATE":return "Ограничение: приблизительная оценка по фото.";case "INCOMPLETE_DIARY":return "Ограничение: дневник заполнен частично.";case "INCOMPLETE_DAY":return "Ограничение: день ещё не завершён.";case "RECOVERY_GAP":return "Ограничение: есть промежутки с неизвестной длительностью или данными.";case "MISSING_EQUIPMENT_ID":return "Ограничение: оборудование упражнения не указано.";default:return "Есть дополнительное ограничение; точная отметка доступна в JSON ниже.";}}
    private static String basisName(String basis){switch(basis){case "registered_days":return "Основа: дни с сохранёнными наблюдениями.";case "usable_records":return "Основа: пригодные сохранённые записи.";case "median_all_valid_saved_points":return "Медиана всех сохранённых пригодных наблюдений.";case "sum_all_valid_values_divided_by_count":return "Среднее всех пригодных наблюдений.";case "confirmed_registered_values_in_selected_days":return "Подтверждённые записи за выбранные дни.";case "mean_selected_eligible_episodes":return "Среднее по сохранённым пригодным интервалам сна.";case "mean_last_observed_cumulative_day_snapshot_not_full_day_total":return "Среднее последних сохранённых дневных значений шагов; не итог полного дня.";case "mean_daily_medians":return "Среднее дневных медиан сохранённых измерений.";case "done_work_sets_excluding_warmup":return "Завершённые рабочие подходы без разминки.";case "sum_stage_3_end_minus_start":return "Сумма зарегистрированных интервалов глубокого сна.";case "same_wake_day_independent_observations_no_causality":return "Независимые наблюдения в совпадающие дни; причинная связь не устанавливается.";default:return "Расчёт по сохранённым локальным данным. Точная формула и контекст — в JSON ниже.";}}
    private void showJson(String title,JSONObject data){android.widget.TextView text=ui.label(pretty(data),12,ui.text);text.setTextIsSelectable(true);text.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));android.widget.ScrollView scroll=new android.widget.ScrollView(activity);scroll.addView(text);ui.dialogBuilder().setTitle(title).setView(scroll).setPositiveButton("Закрыть",null).show();}
    private static String pretty(JSONObject data){try{return data.toString(2);}catch(Exception e){return data.toString();}}
    static String domainName(String domain){switch(domain){case "nutrition":return "Питание";case "activity":return "Активность";case "sleep":return "Сон";case "heart":return "Пульс";case "spo2":return "SpO₂";case "strength":return "Силовые";case "weight":return "Вес";default:return domain;}}
    private static String availability(String value){return "AVAILABLE".equals(value)?"данные доступны":"PARTIAL".equals(value)?"частичные данные":"нет пригодных данных";}
    private static String quality(String value){return "SUFFICIENT".equals(value)?"достаточно для описания":"LIMITED".equals(value)?"вывод ограничен":"данных недостаточно";}
    private static String domainNames(List<String> domains){List<String> labels=new ArrayList<>();for(String d:domains)labels.add(domainName(d));return android.text.TextUtils.join(", ",labels);}
    private void title(LinearLayout p,String value){p.addView(ui.heading(value),ui.fillWrap(10,8));}
    private void note(LinearLayout p,String value){p.addView(ui.label(value,14,ui.muted),ui.fillWrap(4,6));}
    private Button make(String value,Runnable action){return ui.action(value,value.startsWith("Отправить эти данные"),action);}
    private void button(LinearLayout p,String value,Runnable action){p.addView(make(value,action),ui.fillWrap(4,6));}
    private CheckBox check(LinearLayout p,String value,boolean checked){CheckBox c=new CheckBox(activity);c.setText(value);c.setTextColor(ui.text);ui.check(c);c.setChecked(checked);p.addView(c,ui.fillWrap(4,4));return c;}
}



